  /* The table is parsed once, on first use, not at load. A reader who
     never moves the pin still pays only the download. */
  var index = null;

  function parse() {
    if (index) return index;
    index = [];
    var groups = DATA.split('\n');
    for (var g = 0; g < groups.length; g++) {
      var split = groups[g].indexOf(':');
      if (split < 0) continue;
      var cc = groups[g].slice(0, split);
      var rows = groups[g].slice(split + 1).split(';');
      for (var r = 0; r < rows.length; r++) {
        var f = rows[r].split('|');
        if (f.length !== 3) continue;
        index.push({ n: f[0], c: cc, lat: +f[1] / 100, lng: +f[2] / 100 });
      }
    }
    return index;
  }

  /* Equirectangular distance. Over the few hundred kilometres that ever
     decide a winner here the error against the great circle is well under
     the kilometre the stored coordinates are already rounded to. */
  function km(aLat, aLng, bLat, bLng) {
    var dLng = bLng - aLng;
    if (dLng > 180) dLng -= 360;
    if (dLng < -180) dLng += 360;
    var x = dLng * Math.cos((aLat + bLat) * 0.5 * Math.PI / 180);
    var y = bLat - aLat;
    return Math.sqrt(x * x + y * y) * 111.195;
  }

